#include <stdio.h>

enum Kind { INT_KIND, DOUBLE_KIND };

struct Variant {
    enum Kind kind;
    union {
        int i;
        double d;
    } value;
};

void show(struct Variant v) {
    if (v.kind == INT_KIND) {
        printf("int: %d\n", v.value.i);
    } else {
        printf("double: %.2f\n", v.value.d);
    }
}

int main() {
    struct Variant a = {INT_KIND, {.i = 42}};
    struct Variant b = {DOUBLE_KIND, {.d = 3.14}};
    show(a);
    show(b);
    return 0;
}
